uario</label><strong><?=e($profile['nom_usr'])?></strong></div><div class="profile-field"><label>Correo electrónico</label><strong><?=e($profile['mail'])?></strong></div><div class="profile-field"><label>Alias</label><strong><?=e($profile['alias'])?></strong></div><div class="profile-field"><label>Ubicación</label><strong><?=e($profile['dir_usr'] ?: 'Sin ubicación')?></strong></div></div><?php if($profile['biografia']):?><section class="profile-section"><h3>Biografía</h3><p class="profile-note"><?=nl2br(e($profile['biografia']))?></p></section><?php endif;?></section></div></main><?=sideb_footer()?></body></html>
